using static Bootcamp.Check;
using System.Threading.Channels;

async Task<WorkerReport> RunWorker(ChannelReader<Job> jobs, Func<Job, CancellationToken, Task> handle, List<string> log, CancellationToken stoppingToken)
{
    int done = 0, failed = 0;
    try
    {
        while (!stoppingToken.IsCancellationRequested && await jobs.WaitToReadAsync(stoppingToken))
        {
            while (!stoppingToken.IsCancellationRequested && jobs.TryRead(out var job))
            {
                try
                {
                    await handle(job, stoppingToken);
                    done++;
                    log.Add($"done {job.Id}");
                }
                catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
                {
                    log.Add($"stopped {job.Id}");
                }
                catch (Exception e)
                {
                    failed++;
                    log.Add($"failed {job.Id}: {e.Message}");
                }
            }
        }
    }
    catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
    {
        // the wait for the next job was cancelled: a normal stop
    }
    return new WorkerReport(done, failed);
}

