// ─────────────────────────────────────────────────────────────────────────
//  02 · graceful stop with a deadline★★★ core
//  concepts: Complete the writer · drain in order · deadline token · hand back, never drop
// ─────────────────────────────────────────────────────────────────────────
//
//  Stop taking work, finish what fits before the deadline, and give the rest back.

using static Bootcamp.Check;
using System.Threading.Channels;

async Task<StopReport> DrainAndStop(Channel<Job> queue, Func<Job, CancellationToken, Task> handle, Action<Job> handBack, CancellationToken deadline)
{
    queue.Writer.TryComplete();                       // from here on, producers' TryWrite returns false
    int done = 0, failed = 0, handedBack = 0;
    while (queue.Reader.TryRead(out var job))         // completed channels still give up what they hold
    {
        if (deadline.IsCancellationRequested)
        {
            handBack(job);
            handedBack++;
            continue;
        }
        try
        {
            await handle(job, deadline);
            done++;
        }
        catch (OperationCanceledException) when (deadline.IsCancellationRequested)
        {
            handBack(job);                            // cut off mid-job: it did not finish, so it goes back
            handedBack++;
        }
        catch (Exception)
        {
            failed++;
        }
    }
    return new StopReport(done, failed, handedBack);
}

// Given: a queue holding these jobs.
Channel<Job> Queue(params string[] ids)
{
    var channel = Channel.CreateBounded<Job>(new BoundedChannelOptions(10) { FullMode = BoundedChannelFullMode.Wait });
    foreach (var id in ids) channel.Writer.TryWrite(new Job(id));
    return channel;
}


